//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ НАЧАЛОПЕРИОДА(ДОБАВИТЬКДАТЕ(НАЧАЛОПЕРИОДА(ВЫБОР КОГДА &НачалоПериода = ДАТАВРЕМЯ(1, 1, 1) ТОГДА ДАТАВРЕМЯ(1980, 1, 1) ИНАЧЕ &НачалоПериода КОНЕЦ, МЕСЯЦ), МЕСЯЦ, Цифры.Цифра + ЕСТЬNULL(Цифры10.Цифра, 0) * 10 + ЕСТЬNULL(Цифры100.Цифра, 0) * 100 + ЕСТЬNULL(Цифры1000.Цифра, 0) * 1000 + ЕСТЬNULL(Цифры10000.Цифра, 0) * 10000 + ЕСТЬNULL(Цифры100000.Цифра, 0) * 100000), ДЕНЬ) КАК Период ПОМЕСТИТЬ ВТПериоды ИЗ ВТЦифры КАК Цифры ЛЕВОЕ СОЕДИНЕНИЕ ВТЦифры КАК Цифры10 ПО (РАЗНОСТЬДАТ(НАЧАЛОПЕРИОДА(ВЫБОР КОГДА &НачалоПериода = ДАТАВРЕМЯ(1, 1, 1) ТОГДА ДАТАВРЕМЯ(1980, 1, 1) ИНАЧЕ &НачалоПериода КОНЕЦ, МЕСЯЦ), НАЧАЛОПЕРИОДА(ВЫБОР КОГДА КОНЕЦПЕРИОДА(&КонецПериода, МЕСЯЦ) = КОНЕЦПЕРИОДА(ДАТАВРЕМЯ(1, 1, 1), ДЕНЬ) ТОГДА ДОБАВИТЬКДАТЕ(&ТекущаяДата, МЕСЯЦ, 60) ИНАЧЕ &КонецПериода КОНЕЦ, МЕСЯЦ), МЕСЯЦ) > 9) ЛЕВОЕ СОЕДИНЕНИЕ ВТЦифры КАК Цифры100 ПО (РАЗНОСТЬДАТ(НАЧАЛОПЕРИОДА(ВЫБОР КОГДА &НачалоПериода = ДАТАВРЕМЯ(1, 1, 1) ТОГДА ДАТАВРЕМЯ(1980, 1, 1) ИНАЧЕ &НачалоПериода КОНЕЦ, МЕСЯЦ), НАЧАЛОПЕРИОДА(ВЫБОР КОГДА КОНЕЦПЕРИОДА(&КонецПериода, МЕСЯЦ) = КОНЕЦПЕРИОДА(ДАТАВРЕМЯ(1, 1, 1), ДЕНЬ) ТОГДА ДОБАВИТЬКДАТЕ(&ТекущаяДата, МЕСЯЦ, 60) ИНАЧЕ &КонецПериода КОНЕЦ, МЕСЯЦ), МЕСЯЦ) > 99) ЛЕВОЕ СОЕДИНЕНИЕ ВТЦифры КАК Цифры1000 ПО (РАЗНОСТЬДАТ(НАЧАЛОПЕРИОДА(ВЫБОР КОГДА &НачалоПериода = ДАТАВРЕМЯ(1, 1, 1) ТОГДА ДАТАВРЕМЯ(1980, 1, 1) ИНАЧЕ &НачалоПериода КОНЕЦ, МЕСЯЦ), НАЧАЛОПЕРИОДА(ВЫБОР КОГДА КОНЕЦПЕРИОДА(&КонецПериода, МЕСЯЦ) = КОНЕЦПЕРИОДА(ДАТАВРЕМЯ(1, 1, 1), ДЕНЬ) ТОГДА ДОБАВИТЬКДАТЕ(&ТекущаяДата, МЕСЯЦ, 60) ИНАЧЕ &КонецПериода КОНЕЦ, МЕСЯЦ), МЕСЯЦ) > 999) ЛЕВОЕ СОЕДИНЕНИЕ ВТЦифры КАК Цифры10000 ПО (РАЗНОСТЬДАТ(НАЧАЛОПЕРИОДА(ВЫБОР КОГДА &НачалоПериода = ДАТАВРЕМЯ(1, 1, 1) ТОГДА ДАТАВРЕМЯ(1980, 1, 1) ИНАЧЕ &НачалоПериода КОНЕЦ, МЕСЯЦ), НАЧАЛОПЕРИОДА(ВЫБОР КОГДА КОНЕЦПЕРИОДА(&КонецПериода, МЕСЯЦ) = КОНЕЦПЕРИОДА(ДАТАВРЕМЯ(1, 1, 1), ДЕНЬ) ТОГДА ДОБАВИТЬКДАТЕ(&ТекущаяДата, МЕСЯЦ, 60) ИНАЧЕ &КонецПериода КОНЕЦ, МЕСЯЦ), МЕСЯЦ) > 9999) ЛЕВОЕ СОЕДИНЕНИЕ ВТЦифры КАК Цифры100000 ПО (РАЗНОСТЬДАТ(НАЧАЛОПЕРИОДА(ВЫБОР КОГДА &НачалоПериода = ДАТАВРЕМЯ(1, 1, 1) ТОГДА ДАТАВРЕМЯ(1980, 1, 1) ИНАЧЕ &НачалоПериода КОНЕЦ, МЕСЯЦ), НАЧАЛОПЕРИОДА(ВЫБОР КОГДА КОНЕЦПЕРИОДА(&КонецПериода, МЕСЯЦ) = КОНЕЦПЕРИОДА(ДАТАВРЕМЯ(1, 1, 1), ДЕНЬ) ТОГДА ДОБАВИТЬКДАТЕ(&ТекущаяДата, МЕСЯЦ, 60) ИНАЧЕ &КонецПериода КОНЕЦ, МЕСЯЦ), МЕСЯЦ) > 99999) ГДЕ НАЧАЛОПЕРИОДА(ДОБАВИТЬКДАТЕ(НАЧАЛОПЕРИОДА(ВЫБОР КОГДА &НачалоПериода = ДАТАВРЕМЯ(1, 1, 1) ТОГДА ДАТАВРЕМЯ(1980, 1, 1) ИНАЧЕ &НачалоПериода КОНЕЦ, МЕСЯЦ), МЕСЯЦ, Цифры.Цифра + ЕСТЬNULL(Цифры10.Цифра, 0) * 10 + ЕСТЬNULL(Цифры100.Цифра, 0) * 100 + ЕСТЬNULL(Цифры1000.Цифра, 0) * 1000 + ЕСТЬNULL(Цифры10000.Цифра, 0) * 10000 + ЕСТЬNULL(Цифры100000.Цифра, 0) * 100000), ДЕНЬ) МЕЖДУ ВЫБОР КОГДА &НачалоПериода = ДАТАВРЕМЯ(1, 1, 1) ТОГДА ДАТАВРЕМЯ(1980, 1, 1) ИНАЧЕ &НачалоПериода КОНЕЦ И ВЫБОР КОГДА &КонецПериода = КОНЕЦПЕРИОДА(ДАТАВРЕМЯ(1, 1, 1), ДЕНЬ) ТОГДА &КонецПериода ИНАЧЕ &КонецПериода КОНЕЦ
ИНДЕКСИРОВАТЬ ПО Период ;
